account.js.theirs:
'use strict';

class Account {
  constructor() { this._balance = 0; this._audit = []; }

  set balance(value) {
    if (value < 0) throw new RangeError('negative balance');
    this._balance = Math.round(value * 100) / 100;
  }

  deposit(amount) {
    this.balance = this._balance + amount;
  }
}

module.exports = { Account };

